class Solution:
    def addTwoNumbers(self, l1: ListNode, l2: ListNode) -> ListNode:
        head = tail = None
        carry = 0
        while l1 is not None or l2 is not None:
            n1, n2 = 0, 0
            if l1 is not None:
                n1 = l1.val
                l1 = l1.next
            if l2 is not None:
                n2 = l2.val
                l2 = l2.next
            s = n1 + n2 + carry
            s, carry = s % 10, s // 10
            if head is None:
                head = ListNode(s)
                tail = head
            else:
                tail.next = ListNode(s)
                tail = tail.next
        if carry > 0:
            tail.next = ListNode(carry)
        return head
